
CREATE TABLE public.sorteio_premios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, nome text NOT NULL, descricao text, imagem_url text, quantidade_estoque integer NOT NULL DEFAULT 0, ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), programa_id uuid REFERENCES public.programas(id) ON DELETE SET NULL, dias_validade integer NOT NULL DEFAULT 7);
CREATE TABLE public.sorteio_sorteios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, premio_id uuid NOT NULL REFERENCES public.sorteio_premios(id) ON DELETE CASCADE, ouvinte_id uuid REFERENCES public.ouvintes(id) ON DELETE SET NULL, nome_ganhador text NOT NULL, telefone_ganhador text, data_sorteio timestamptz NOT NULL DEFAULT now(), entregue boolean NOT NULL DEFAULT false, data_entrega timestamptz, observacoes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), expirado boolean NOT NULL DEFAULT false, data_expiracao timestamptz);
